// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame, ERC20Interface} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;

    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(uint256 tokens, bool transferSucceeds) public {
        MockToken token = new MockToken(transferSucceeds);
        bool ok = c.transferAnyERC20Token(address(token), address(this), tokens);
        assertTrue(ok == transferSucceeds);
    }
}

contract MockToken is ERC20Interface {
    bool public shouldSucceed;
    constructor(bool s) { shouldSucceed = s; }
    function transfer(address to, uint256 tokens) override public returns (bool success) {
        return shouldSucceed;
    }
}
